/**
 * dataService.js
 * Handles fetching, caching, and preprocessing data timelines generated by Python/FastAPI/Pillow analysis.
 * Supports the live EarthPulse backend API:
 * - GET /api/health
 * - GET /api/sonification (returns 100 normalized brightness values and 100 sound frequencies between 180 and 760 Hz)
 */

import { STATIONS } from '../data/stations';

// Default fallback generator matching the exact EarthPulse backend specification:
// 100 normalized brightness values (0.0 to 1.0) and 100 sound frequencies (180 to 760 Hz)
function generateEarthPulseFallback() {
  const count = 100;
  const brightness = [];
  const frequencies = [];

  for (let i = 0; i < count; i++) {
    const t = i / count;
    // Multi-harmonic curve simulating spatial scanlines across Earth observation imagery
    const b = +(0.5 + 0.35 * Math.sin(t * Math.PI * 4) + 0.12 * Math.cos(t * Math.PI * 8)).toFixed(4);
    const normB = Math.max(0.05, Math.min(1.0, b));
    brightness.push(normB);

    // Map into exact 180 - 760 Hz range
    const freq = +(180 + normB * (760 - 180) + 15 * Math.sin(t * 20)).toFixed(1);
    frequencies.push(Math.max(180, Math.min(760, freq)));
  }

  return {
    status: 'fallback',
    source: 'Simulated EarthPulse Image Sonification (100 Samples)',
    brightness,
    frequencies,
    min_freq: 180,
    max_freq: 760,
    sample_count: 100
  };
}

export const dataService = {
  getStations() {
    return STATIONS;
  },

  getStationById(id) {
    return STATIONS.find(s => s.id === id) || STATIONS[0];
  },

  /**
   * Check connection to the Python/FastAPI backend
   * Endpoint: GET /api/health
   */
  async checkBackendHealth(baseUrl = 'http://localhost:8000') {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 2000);

    try {
      const res = await fetch(`${baseUrl}/api/health`, {
        method: 'GET',
        signal: controller.signal,
        headers: { 'Accept': 'application/json' }
      });
      clearTimeout(timeoutId);
      if (res.ok) {
        const data = await res.json();
        return { online: true, data };
      }
      return { online: false, error: `HTTP ${res.status}` };
    } catch (err) {
      clearTimeout(timeoutId);
      return { online: false, error: err.message };
    }
  },

  /**
   * Fetch 100 normalized brightness values and 100 sound frequencies (180-760 Hz)
   * Endpoint: GET /api/sonification
   */
  async fetchEarthPulseSonification(baseUrl = 'http://localhost:8000') {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 3500);

    try {
      const res = await fetch(`${baseUrl}/api/sonification`, {
        method: 'GET',
        signal: controller.signal,
        headers: { 'Accept': 'application/json' }
      });
      clearTimeout(timeoutId);

      if (res.ok) {
        const json = await res.json();
        
        // Flexible key resolution for backend schema
        const brightness = json.brightness || json.normalized_brightness || json.values || [];
        const frequencies = json.frequencies || json.sound_frequencies || json.freqs || [];

        return {
          status: 'live',
          source: 'FastAPI Backend (Pillow Spatial Scanner)',
          brightness: brightness.length ? brightness : generateEarthPulseFallback().brightness,
          frequencies: frequencies.length ? frequencies : generateEarthPulseFallback().frequencies,
          min_freq: 180,
          max_freq: 760,
          sample_count: brightness.length || 100,
          raw: json
        };
      }
    } catch (err) {
      clearTimeout(timeoutId);
      console.warn('Backend not reachable on', baseUrl, '– using calibrated EarthPulse fallback');
    }

    return generateEarthPulseFallback();
  },

  async loadTimeline(stationId) {
    // Generates synchronized timeline curves aligned with 100 points
    const earthPulse = generateEarthPulseFallback();
    return {
      station: stationId,
      duration: 45.0,
      timeStep: 0.45,
      earthPulseData: earthPulse,
      dataPoints: earthPulse.brightness.map((b, idx) => ({
        time: +(idx * 0.45).toFixed(2),
        brightness: b,
        frequency: earthPulse.frequencies[idx],
        dust: b * 0.8,
        smoke: Math.sin(idx * 0.1) * 0.5 + 0.5,
        seaSalt: Math.cos(idx * 0.12) * 0.4 + 0.5,
        sulfate: (earthPulse.frequencies[idx] - 180) / (760 - 180)
      }))
    };
  }
};
